#include <bits/stdc++.h>
using namespace std;

struct Orientation {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> transformed;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                transformed.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : transformed) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : transformed) { x -= minx; y -= miny; }
            sort(transformed.begin(), transformed.end());
            if (seen.insert(transformed).second) {
                int maxx = 0, maxy = 0;
                for (auto [x, y] : transformed) { maxx = max(maxx, x); maxy = max(maxy, y); }
                res.push_back({transformed, maxx + 1, maxy + 1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> rawCells(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        cin >> ksz[i];
        rawCells[i].resize(ksz[i]);
        for (int j = 0; j < ksz[i]; j++) {
            cin >> rawCells[i][j].first >> rawCells[i][j].second;
        }
        totalCells += ksz[i];
    }

    vector<vector<Orientation>> allOrients(n);
    for (int i = 0; i < n; i++) {
        allOrients[i] = getOrientations(rawCells[i]);
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (ksz[a] != ksz[b]) return ksz[a] > ksz[b];
        return allOrients[a].size() < allOrients[b].size();
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    int sqrtArea = max(1, (int)ceil(sqrt((double)totalCells)));

    vector<int> candidateW;
    for (int w = max(1, sqrtArea - 5); w <= sqrtArea + 100 && w <= totalCells; w++) {
        candidateW.push_back(w);
    }

    auto startTime = chrono::steady_clock::now();

    for (int W : candidateW) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 8500) break;

        int H_alloc = totalCells / W + n + 50;
        // Use a flat grid
        vector<bool> grid((long long)W * H_alloc, false);
        vector<int> colH(W, 0);

        vector<int> px(n), py(n), pr(n), pf(n);
        bool valid = true;
        int currentMaxH = 0;

        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];
            int bestScore = INT_MAX;
            int bx=-1, by=-1, bor=-1;

            for (int oi = 0; oi < (int)allOrients[i].size(); oi++) {
                auto& ori = allOrients[i][oi];
                if (ori.w > W) continue;

                for (int x = 0; x <= W - ori.w; x++) {
                    int minY = 0;
                    for (auto [cx, cy] : ori.cells) {
                        minY = max(minY, colH[x + cx] - cy);
                    }
                    if (minY < 0) minY = 0;

                    for (int y = minY; y + ori.h <= H_alloc; y++) {
                        bool ok = true;
                        for (auto [cx, cy] : ori.cells) {
                            if (grid[(long long)(x+cx)*H_alloc + (y+cy)]) { ok = false; break; }
                        }
                        if (ok) {
                            int mH = max(currentMaxH, y + ori.h);
                            int score = mH * 100000 + y * 100 + x;
                            if (score < bestScore) {
                                bestScore = score; bx=x; by=y; bor=oi;
                            }
                            break; // found lowest y for this x,ori
                        }
                    }
                }
            }

            if (bx < 0) { valid = false; break; }

            auto& cho = allOrients[i][bor];
            px[i] = bx; py[i] = by; pr[i] = cho.r; pf[i] = cho.f;
            for (auto [cx, cy] : cho.cells) {
                grid[(long long)(bx+cx)*H_alloc + (by+cy)] = true;
                colH[bx+cx] = max(colH[bx+cx], by+cy+1);
                currentMaxH = max(currentMaxH, by+cy+1);
            }
        }

        if (!valid) continue;

        int H = currentMaxH;
        int area = W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area;
            bestW = W; bestH = H;
            bestX = px; bestY = py; bestR = pr; bestF = pf;
        }
    }

    if (bestArea == INT_MAX) {
        // Fallback: place each piece in a single row
        int W = totalCells + n*10;
        int cx = 0;
        bestW = 0; bestH = 0;
        for (int i = 0; i < n; i++) {
            auto& ori = allOrients[i][0];
            bestX[i] = cx; bestY[i] = 0; bestR[i] = ori.r; bestF[i] = ori.f;
            cx += ori.w;
            bestW = max(bestW, cx);
            bestH = max(bestH, ori.h);
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
    }
    return 0;
}
